import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    points = [(data[i], data[i + 1]) for i in range(1, len(data), 2)]
    points.sort()
    y = [v for _, v in points]

    # Count nonempty maximal antichains, represented by decreasing subsequences.
    dp = [0] * n
    for i in range(n):
        # No selected point before i: all preceding points must be comparable to i.
        if all(y[k] < y[i] for k in range(i)):
            dp[i] = 1
        for j in range(i):
            if y[j] <= y[i]:
                continue
            # Every point in the gap must be comparable to one of the endpoints.
            if all(y[k] < y[i] or y[k] > y[j] for k in range(j + 1, i)):
                dp[i] = (dp[i] + dp[j]) % MOD

    answer = 1  # Performing no operation leaves the entire set unchanged.
    for i in range(n):
        # All points after the final selected point must be comparable to it.
        if all(y[k] > y[i] for k in range(i + 1, n)):
            answer = (answer + dp[i]) % MOD
    print(answer)

if __name__ == '__main__':
    main()

