import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    groups = [[] for _ in range(n)]
    pos = 2
    for _ in range(m):
        l, r, x = data[pos] - 1, data[pos + 1] - 1, data[pos + 2] - 1
        pos += 3
        groups[x].append((l, r))

    # For center k and segment [a,b], a forbidden interval exists iff
    # some interval [l,r] centered at k has l >= a and r <= b.
    suffix_min_right = []
    for k in range(n):
        q = [n] * (n + 1)
        for l, r in groups[k]:
            if r < q[l]:
                q[l] = r
        for a in range(n - 1, -1, -1):
            if q[a + 1] < q[a]:
                q[a] = q[a + 1]
        suffix_min_right.append(q)

    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

    dp = [[0] * n for _ in range(n)]
    for length in range(1, n + 1):
        for a in range(n - length + 1):
            b = a + length - 1
            total = 0
            for k in range(a, b + 1):
                if suffix_min_right[k][a] <= b:
                    continue
                left_len = k - a
                right_len = b - k
                left_count = dp[a][k - 1] if left_len else 1
                right_count = dp[k + 1][b] if right_len else 1
                total += left_count * right_count * comb[length - 1][left_len]
            dp[a][b] = total % MOD

    print(dp[0][n - 1])

