import sys
MOD=998244353

def factor(x):
    result = []
    d = 2
    while d * d <= x:
        if x % d == 0:
            e = 0
            while x % d == 0:
                x //= d
                e += 1
            result.append((d, e))
        d += 1
    if x > 1:
        result.append((x, 1))
    return result

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = [factor(x) for x in data[1:]]
    primes = {p for row in factors for p, _ in row}
    answer = 1

    for p in primes:
        edges = [next((e for q, e in row if q == p), 0) for row in factors]
        radius = sum(edges)
        contribution = 0
        # Fix the minimum cumulative valuation m. Retain only walks at or above m
        # that touch m, so each choice of signs is counted exactly once.
        for m in range(-radius, 1):
            dp = {(0, m == 0): 1}
            for e in edges:
                nxt = {}
                for (c, touched), value in dp.items():
                    targets = (c,) if e == 0 else (c + e, c - e)
                    for nc in targets:
                        if nc < m:
                            continue
                        state = (nc, touched or nc == m)
                        nxt[state] = (nxt.get(state, 0) + value * pow(p, nc, MOD)) % MOD
                dp = nxt
            subtotal = sum(value for (c, touched), value in dp.items() if touched) % MOD
            scale = pow(pow(p, m, MOD), -n, MOD)
            contribution = (contribution + subtotal * scale) % MOD
        answer = answer * contribution % MOD

    print(answer)

solve()

