def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, k = data[:3]
    a = data[3:]
    # dp[x][r] counts subsets with XOR x and size congruent to r mod m.
    # Process each element in-place from a snapshot so it is used at most once.
    dp = {0: [1] + [0] * (m - 1)}
    for v in a:
        ndp = {x: row[:] for x, row in dp.items()}
        for x, row in dp.items():
            y = x ^ v
            dest = ndp.get(y)
            if dest is None:
                dest = [0] * m
                ndp[y] = dest
            for r, c in enumerate(row):
                if c:
                    dest[(r + 1) % m] = (dest[(r + 1) % m] + c) % MOD
        dp = ndp
    ans = 0
    for x, row in dp.items():
        ans = (ans + pow(x, k, MOD) * row[0]) % MOD
    # Remove the empty subsequence; its contribution is zero in any case.
    print(ans)

