    it = iter(data)
    n = next(it)
    m = next(it)
    q = next(it)

    edges = [(next(it) - 1, next(it) - 1, next(it)) for _ in range(m)]
    queries = []
    ever_closed = set()
    for _ in range(q):
        t = next(it)
        if t == 1:
            idx = next(it) - 1
            queries.append((1, idx))
            ever_closed.add(idx)
        else:
            x = next(it) - 1
            y = next(it) - 1
            queries.append((2, x, y))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for idx, (u, v, w) in enumerate(edges):
        if idx not in ever_closed:
            dist[u][v] = dist[v][u] = w

    # APSP in the graph after all forward-time closures.
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            di = dist[i]
            for j in range(n):
                cand = dik + dk[j]
                if cand < di[j]:
                    di[j] = cand

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            _, x, y = query
            answers.append(-1 if dist[x][y] == inf else dist[x][y])
        else:
            _, idx = query
            u, v, w = edges[idx]
            # Inserting one edge: any newly shorter path uses it once.
            du = [dist[i][u] for i in range(n)]
            dv = [dist[i][v] for i in range(n)]
            for i in range(n):
                di = dist[i]
                iu, iv = du[i], dv[i]
