import sys
import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = []
    idx = 2
    for _ in range(n):
        a, p, b, q = data[idx:idx + 4]
        idx += 4
        g = math.gcd(a, b)
        # Replacing b/g S-machines by a/g T-machines preserves capacity.
        # Bound the count of whichever type is not more expensive to replace.
        if (b // g) * p >= (a // g) * q:
            processes.append((a, p, b, q, 0, b // g))
        else:
            processes.append((a, p, b, q, 1, a // g))

    def feasible(target):
        total = 0
        for a, p, b, q, mode, limit in processes:
            best = 10**30
            if mode == 0:
                for k in range(limit):
                    remaining = target - k * a
                    t_count = max(0, (remaining + b - 1) // b)
                    cost = k * p + t_count * q
                    if cost < best:
                        best = cost
            else:
                for k in range(limit):
                    remaining = target - k * b
                    s_count = max(0, (remaining + a - 1) // a)
                    cost = k * q + s_count * p
                    if cost < best:
                        best = cost
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1
    print(low)

if __name__ == '__main__':
    main()

