class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Number of popcount-reduction steps needed for each possible
        # Hamming weight. For x > 1, steps(x) = 1 + steps(popcount(x)).
        steps = [0] * (n + 1)
        for x in range(2, n + 1):
            steps[x] = 1 + steps[x.bit_count()]

        # Pascal triangle: choose[r][q] = C(r, q).
        choose = [[0] * (n + 1) for _ in range(n + 1)]
        choose[0][0] = 1
        for r in range(1, n + 1):
            choose[r][0] = choose[r][r] = 1
            for q in range(1, r):
                choose[r][q] = (choose[r - 1][q - 1] + choose[r - 1][q]) % MOD

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                # Make this position 0 (so the candidate is smaller than s),
                # then select the required number of ones in the suffix.
                for total_ones in range(1, n + 1):
                    if steps[total_ones] <= k - 1:
                        needed = total_ones - prefix_ones
                        if 0 <= needed <= remaining:
                            answer += choose[remaining][needed]
                prefix_ones += 1

        return answer % MOD

