    for _ in range(m):
        s=next(it)-1; t=next(it)-1
        people.append((min(s,t),max(s,t),s<t))
    queries=[(next(it)-1,next(it)-1) for _ in range(q)]
    out=[]
    for l,r in queries:
        parent=list(range(n)); rank=[0]*n
        def find(x):
            while parent[x]!=x:
                parent[x]=parent[parent[x]]; x=parent[x]
            return x
        for i in range(l,r+1):
            a,b,_=people[i]
            x=find(a); y=find(b)
            if x!=y:
                if rank[x]<rank[y]: x,y=y,x
                parent[y]=x
                if rank[x]==rank[y]:rank[x]+=1
        # An ascending traveler requires endpoint value < all internal values;
        # descending requires endpoint value > all internal values.
        graph=[set() for _ in range(n)]; indeg=[0]*n; bad=False
        for i in range(l,r+1):
            a,b,asc=people[i]; x=find(a)
            for v in range(a+1,b):
                y=find(v)
                if x==y:
                    bad=True; break
                u,z=(x,y) if asc else (y,x)
                if z not in graph[u]:
                    graph[u].add(z); indeg[z]+=1
            if bad: break
        if bad:
            out.append('No'); continue
        dq=deque(i for i in range(n) if find(i)==i and indeg[i]==0)
