class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        size = n * m
        # States are split into compact arrays by direction and expected value.
        straight = [[array('H', [0]) * size for _ in range(2)] for _ in range(4)]
        turned = [[array('H', [0]) * size for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                base = r * m
                for c in cols:
                    idx = base + c
                    for ei, value in enumerate((0, 2)):
                        if grid[r][c] != value:
                            continue
                        nr, nc = r + dr, c + dc
                        length = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            length += straight[d][1 - ei][nr * m + nc]
                        straight[d][ei][idx] = length
        for d, (dr, dc) in enumerate(dirs):
            nd = (d + 1) % 4
            trd, tcd = dirs[nd]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                base = r * m
                for c in cols:
                    idx = base + c
                    for ei, value in enumerate((0, 2)):
                        if grid[r][c] != value:
                            continue
                        length = 1
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            length = max(length, 1 + turned[d][1 - ei][nr * m + nc])
                        nr, nc = r + trd, c + tcd
                        if 0 <= nr < n and 0 <= nc < m:
                            length = max(length, 1 + straight[nd][1 - ei][nr * m + nc])
                        turned[d][ei][idx] = length
        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(dirs):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                        answer = max(answer, 1 + turned[d][1][nr * m + nc])
        return answer

