    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # 10^i modulo k for all positions.
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        # The coefficient of each freely chosen digit in the number's residue.
        coeff = []
        for i in range(m):
            j = n - 1 - i
            if i == j:
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[j]) % k)

        # dp[i] is a bitmask of residues achievable by positions i onward.
        dp = [0] * (m + 1)
        dp[m] = 1  # Empty suffix contributes residue zero.
        for i in range(m - 1, -1, -1):
            mask = 0
            c = coeff[i]
            old = dp[i + 1]
            for digit in range(10):
                shift = digit * c % k
                for residue in range(k):
                    if (old >> residue) & 1:
                        mask |= 1 << ((residue + shift) % k)
            dp[i] = mask

        # Greedily choose the largest digit that still permits a completion.
        chosen = []
        current = 0
        for i, c in enumerate(coeff):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-(current + digit * c)) % k
                if (dp[i + 1] >> needed) & 1:
                    chosen.append(str(digit))
                    current = (current + digit * c) % k
                    break

        first_half = ''.join(chosen)
        if n % 2:
            return first_half + first_half[:-1][::-1]
        return first_half + first_half[::-1]

