import sys
from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[0], data[1]
    funcs = list(zip(data[2::2], data[3::2]))

    # In the optimal order from outermost to innermost, i precedes j iff
    # (A_i - 1) / B_i >= (A_j - 1) / B_j. Process the reverse order below.
    def compare(x, y):
        diff = (x[0] - 1) * y[1] - (y[0] - 1) * x[1]
        return (diff > 0) - (diff < 0)

    funcs.sort(key=cmp_to_key(compare))  # innermost to outermost

    # dp[t] is the greatest value obtainable after choosing t functions
    # among the processed functions, with the current value being their input.
    dp = [-1] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for t in range(k, 0, -1):
            if dp[t - 1] >= 0:
                dp[t] = max(dp[t], a * dp[t - 1] + b)

    print(dp[k])

if __name__ == '__main__':
    main()

