from typing import List
class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n=len(edges)+1
        g=[[] for _ in range(n)]
        for u,v,w in edges:
            g[u].append((v,w)); g[v].append((u,w))
        par=[-1]*n; pw=[0]*n; order=[0]
        par[0]=0
        for u in order:
            for v,w in g[u]:
                if v==par[u]: continue
                par[v]=u; pw[v]=w; order.append(v)
        absent=[0]*n; present=[0]*n
        for u in reversed(order):
            base=0; gains=[]
            for v,w in g[u]:
                if par[v]==u:
                    base += absent[v]
                    gains.append(w+present[v]-absent[v])
            gains.sort(reverse=True)
            pos=[x for x in gains if x>0]
            absent[u]=base+sum(pos[:k])
            present[u]=base+sum(pos[:max(0,k-1)])
        return absent[0]

