class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first = p.index('*')
        second = p.index('*', first + 1)
        parts = (p[:first], p[first + 1:second], p[second + 1:])
        n = len(s)

        def occurrences(word):
            if not word:
                return list(range(n + 1))
            m = len(word)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                pi[i] = j
            found = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    found.append(i - m + 1)
                    j = pi[j - 1]
            return found

        a_positions, b_positions, c_positions = map(occurrences, parts)
        best = n + 1
        la, lb, lc = map(len, parts)
        for a in a_positions:
