import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    pos = 2
    for _ in range(m):
        x, y, z = data[pos] - 1, data[pos + 1] - 1, data[pos + 2]
        pos += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    potential = [None] * n
    answer = [0] * n
    for start in range(n):
        if potential[start] is not None:
            continue
        potential[start] = 0
        queue = [start]
        component = []
        for v in queue:
            component.append(v)
            for w, z in adj[v]:
                expected = potential[v] ^ z
                if potential[w] is None:
                    potential[w] = expected
                    queue.append(w)
                elif potential[w] != expected:
                    print(-1)
                    return

        ones = [0] * 30
        for v in component:
            value = potential[v]
            for bit in range(30):
                ones[bit] += (value >> bit) & 1

        # A[v] = potential[v] XOR t within this component. Choose each
        # bit of t to make the number of resulting ones as small as possible.
        t = 0
        size = len(component)
        for bit in range(30):
            if ones[bit] > size - ones[bit]:
                t |= 1 << bit
        for v in component:
            answer[v] = potential[v] ^ t

    print(*answer)

if __name__ == '__main__':
    main()

