import sys

def feasible(a, b, d):
    # Partition the ordered particles into nonempty consecutive groups,
    # one group for each target position.
    n, m = len(a), len(b)
    if n < m:
        return False
    j = 0
    for x in b:
        lo, hi = x-d, x+d
        # Every particle assigned to this target must lie in its interval.
        start = j
        while j < n and lo <= a[j] <= hi:
            j += 1
        if j == start:
            return False
        # Reserve at least one particle for every remaining target.
        if n-j < m-b.index(x)-1:
            return False
    return j == n

def solve_case(A, B):
    a = [i for i,c in enumerate(A) if c=='1']
    b = [i for i,c in enumerate(B) if c=='1']
    if len(a) < len(b):
        return -1
    lo, hi = 0, len(A)
    while lo < hi:
        mid = (lo+hi)//2
        if feasible(a,b,mid): hi=mid
        else: lo=mid+1
    return lo

def main():
    data=sys.stdin.buffer.read().split()
    t=int(data[0]); p=1; out=[]
    for _ in range(t):
        n=int(data[p]); A=data[p+1].decode(); B=data[p+2].decode(); p+=3
        out.append(str(solve_case(A,B)))
    print('\n'.join(out))
if __name__=='__main__': main()

