from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Iterative postorder; children are processed in increasing order.
        order = []
        stack = [(0, False)]
        while stack:
            v, visited = stack.pop()
            if visited:
                order.append(v)
            else:
                stack.append((v, True))
                for child in reversed(children[v]):
                    stack.append((child, False))

        pos = [0] * n
        for i, v in enumerate(order):
            pos[v] = i

        # In postorder, each subtree's size is ready before its parent.
        size = [1] * n
        for v in order:
            if v != 0:
                size[parent[v]] += size[v]

        text = ''.join(s[v] for v in order)

        # Manacher radii for odd-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        # even[i] is the radius around the gap immediately before i.
        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for v in range(n):
            end = pos[v]
            length = size[v]
            start = end - length + 1
            if length % 2:
                answer[v] = odd[(start + end) // 2] >= length // 2 + 1
            else:
                answer[v] = even[(start + end + 1) // 2] >= length // 2
        return answer

