class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        for _ in range(t):
            nxt = [0] * 26
            # Characters a through y each advance by one letter.
            for i in range(25):
                nxt[i + 1] = counts[i]
            # Every z produces one a and one b.
            nxt[0] = counts[25]
            nxt[1] = (nxt[1] + counts[25]) % mod
            counts = [value % mod for value in nxt]

        return sum(counts) % mod

