import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        def is_prime(x: int) -> bool:
            if x < 2:
                return False
            d = 2
            while d * d <= x:
                if x % d == 0:
                    return False
                d += 1
            return True

        if is_prime(n) or is_prime(m):
            return -1

        lower = 10 ** (len(str(n)) - 1)
        upper = 10 ** len(str(n))
        distances = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distances.get(value):
                continue
            if value == m:
                return cost

            place = 1
            while place < upper:
                digit = value // place % 10
                for next_digit in (digit - 1, digit + 1):
                    if not 0 <= next_digit <= 9:
                        continue
                    next_value = value + (next_digit - digit) * place
                    # Keep the original number of digits; the leading digit cannot be zero.
                    if next_value < lower or is_prime(next_value):
                        continue
                    next_cost = cost + next_value
                    if next_cost < distances.get(next_value, float('inf')):
                        distances[next_value] = next_cost
                        heapq.heappush(heap, (next_cost, next_value))
                place *= 10

        return -1

