from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] = LCP(nums, nums[i:])
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0
        # Fix the first cut i. A local Z-array gives LCP(nums[i:], nums[i+d:])
        # for every possible length d of the second segment.
        for i in range(1, n - 1):
            m = n - i
            local_z = [0] * m
            left = right = 0
            for d in range(1, m):
                if d < right:
                    local_z[d] = min(right - d, local_z[d - left])
                while d + local_z[d] < m and nums[i + local_z[d]] == nums[i + d + local_z[d]]:
                    local_z[d] += 1
                if d + local_z[d] > right:
                    left, right = d, d + local_z[d]

            first_condition = z[i] >= i
            # d ranges over positive second-segment lengths; d < m leaves nums3 nonempty.
            for d in range(1, m):
                if first_condition or local_z[d] >= d:
                    answer += 1

        return answer

