import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reverse each edge so that traversing outward from 0 follows paths
        # that lead toward 0 in the original graph.
        reverse = [[] for _ in range(n)]
        for a, b, w in edges:
            reverse[b].append((a, w))

        inf = float('inf')
        bottleneck = [inf] * n
        bottleneck[0] = 0
        heap = [(0, 0)]

        while heap:
            cost, node = heapq.heappop(heap)
            if cost != bottleneck[node]:
                continue
            for prev, weight in reverse[node]:
                candidate = max(cost, weight)
                if candidate < bottleneck[prev]:
                    bottleneck[prev] = candidate
                    heapq.heappush(heap, (candidate, prev))

        if any(value == inf for value in bottleneck):
            return -1
        # Since threshold >= 1, one outgoing edge per nonzero node suffices:
        # keep a path toward 0 for each node.
        return max(bottleneck)

