    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set("aeiou")
        answer = 0
        n = len(word)

        # Fix each left endpoint and extend the right endpoint, maintaining
        # the vowel set and consonant count for the current substring.
        for left in range(n):
            seen_vowels = set()
            consonants = 0
            for right in range(left, n):
                ch = word[right]
                if ch in vowels:
                    seen_vowels.add(ch)
                else:
                    consonants += 1

                if consonants == k and len(seen_vowels) == 5:
