    vs=set('aeiou'); ans=0
    for i in range(len(w)):
        seen=set(); c=0
        for j in range(i,len(w)):
            if w[j] in vs: seen.add(w[j])
            else: c+=1
            ans += (c==k and len(seen)==5)
    return ans
def ref(w,k):
    ans=0
    for i in range(len(w)):
        for j in range(i+1,len(w)+1):
            s=w[i:j]
            ans += (set('aeiou') <= set(s) and sum(ch not in 'aeiou' for ch in s)==k)
    return ans
for _ in range(500):
    n=random.randint(5,14); w=''.join(random.choice('aeioux') for _ in range(n)); k=random.randrange(n-4)
    assert fast(w,k)==ref(w,k),(w,k)
print('500 randomized comparisons passed')

class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set("aeiou")
        answer = 0
        n = len(word)

        # Fix each left endpoint and extend the right endpoint, maintaining
        # the vowel set and consonant count for the current substring.
        for left in range(n):
            seen_vowels = set()
            consonants = 0
            for right in range(left, n):
                ch = word[right]
                if ch in vowels:
                    seen_vowels.add(ch)
                else:
                    consonants += 1

                if consonants == k and len(seen_vowels) == 5:
                    answer += 1

        return answer

