def candidate(P):
    s=set(P); best=-1
    for x1,x2 in combinations(sorted({x for x,y in P}),2):
      for y1,y2 in combinations(sorted({y for x,y in P}),2):
        cs={(x1,y1),(x1,y2),(x2,y1),(x2,y2)}
        if cs<=s and not any(x1<=x<=x2 and y1<=y<=y2 and (x,y) not in cs for x,y in s):
          best=max(best,(x2-x1)*(y2-y1))
    return best
# Independent reference: enumerate point quadruples, identify distinct x/y pairs, then validate all points.
def ref(P):
    ans=-1
    for q in combinations(P,4):
      xx=sorted({a for a,b in q}); yy=sorted({b for a,b in q})
      if len(xx)!=2 or len(yy)!=2: continue
      corners={(x,y) for x in xx for y in yy}
      if set(q)!=corners: continue
      if any(xx[0]<=x<=xx[1] and yy[0]<=y<=yy[1] and (x,y) not in corners for x,y in P): continue
      ans=max(ans,(xx[1]-xx[0])*(yy[1]-yy[0]))
    return ans
