import random

def proposed(a,b):
    lo=max(x-y for y,(x,z) in zip(a,b))
    hi=min(z-y for y,(x,z) in zip(a,b))
    return max(0,hi-lo+1)

def brute(a,b):
    vals=[range(x,z+1) for x,z in b]
    return sum(all(c[i]-c[i-1]==a[i]-a[i-1] for i in range(1,len(a))) for c in product(*vals))
